from datetime import datetime

from util.date_time_util import build_standard_utc_timestamp_str


def api():
    def decorator(func):
        def wrapper(event, context):
            message = {
                "timestamp": build_standard_utc_timestamp_str(datetime.utcnow()),
                "log_type": "app_log",
                "event_type": "api_request",
                "data": event
            }
            print(message)

            return func(event, context)

        return wrapper

    return decorator
